#!/bin/bash
UV=<pod-home>/.local/bin/uv
cd /workspace/repo
( rm -rf /workspace/venv-bposd && $UV venv --python 3.12.14 /workspace/venv-bposd && export VIRTUAL_ENV=/workspace/venv-bposd && $UV pip install torch==2.11.0 --index-url https://download.pytorch.org/whl/cpu && $UV pip install numpy==2.5.3 scipy==1.18.1 stim==1.16.0 PyMatching==2.4.0 safetensors==0.8.0 cudaq-qec-cu12==0.8.0 && /workspace/venv-bposd/bin/python -c "import cudaq_qec, numpy, torch; print('bposd env ok', numpy.__version__, torch.__version__)"; echo BPOSD ENV DONE ) > logs/env_bposd.log 2>&1 &
( rm -rf /workspace/venv-trt && $UV venv --python 3.12.14 /workspace/venv-trt && export VIRTUAL_ENV=/workspace/venv-trt && $UV pip install torch==2.11.0 --index-url https://download.pytorch.org/whl/cu126 && $UV pip install -r requirements.txt hydra-core==1.3.7 omegaconf==2.3.1 ldpc==2.4.1 beliefmatching==0.2.0 && $UV pip install tensorrt_cu12==10.14.1.48.post1 nvidia-modelopt==0.47.0 onnx==1.21.0 onnxruntime-gpu==1.24.4 onnxscript==0.7.2 onnx_graphsurgeon==0.6.1 polygraphy==0.53.6 onnxslim==0.1.97 onnxconverter-common==1.16.0 onnx-ir==1.0.0 cupy-cuda12x==14.2.0 ml_dtypes==0.6.0 lief==1.0.0 cppimport==26.4.17 && /workspace/venv-trt/bin/python -c "import tensorrt, modelopt, torch; print('trt env ok', tensorrt.__version__, modelopt.__version__, torch.__version__)"; echo TRT ENV DONE ) > logs/env_trt.log 2>&1 &
wait
